"""
Generate SVG coverage badges from pytest-cov JSON or direct values.

Usage:
    python .github/badges/generate_badges.py

Requires: pytest-cov (for --cov-report=json) or hardcoded fallback.

Outputs:
    .github/badges/coverage-agentic-finance.svg
    .github/badges/coverage-hft-engine.svg
    .github/badges/coverage-total.svg
"""

import json
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
COV_JSON = os.path.join(ROOT, "coverage.json")


def color(pct: float) -> str:
    if pct >= 90:
        return "brightgreen"
    if pct >= 80:
        return "green"
    if pct >= 70:
        return "yellowgreen"
    if pct >= 60:
        return "yellow"
    if pct >= 50:
        return "orange"
    return "red"


def hex_color(pct: float) -> str:
    if pct >= 90:
        return "#4c1"
    if pct >= 80:
        return "#97ca00"
    if pct >= 70:
        return "#a4a61d"
    if pct >= 60:
        return "#dfb317"
    if pct >= 50:
        return "#fe7d37"
    return "#e05d44"


def make_svg(label: str, value: str, pct: float) -> str:
    h = hex_color(pct)
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{len(label) * 7 + 60 + len(value) * 7}" height="20">'
        f'<linearGradient id="b" x2="0" y2="1"><stop offset="0" stop-color="#bbb" stop-opacity=".1"/>'
        f'<stop offset="1" stop-opacity=".1"/></linearGradient>'
        f'<mask id="a"><rect width="100%" height="20" rx="3" fill="#fff"/></mask>'
        f'<g mask="url(#a)">'
        f'<rect width="{len(label) * 7 + 30}" height="20" fill="#555"/>'
        f'<rect x="{len(label) * 7 + 30}" width="{len(value) * 7 + 30}" height="20" fill="{h}"/>'
        f'<rect width="100%" height="20" fill="url(#b)"/></g>'
        f'<g fill="#fff" font-family="DejaVu Sans,Verdana,Geneva,sans-serif" font-size="11">'
        f'<text x="{len(label) * 3 + 5}" y="15" fill="#010101" fill-opacity=".3">{label}</text>'
        f'<text x="{len(label) * 3 + 5}" y="14">{label}</text>'
        f'<text x="{len(label) * 7 + 30 + len(value) * 3 + 5}" y="15" fill="#010101" fill-opacity=".3">{value}</text>'
        f'<text x="{len(label) * 7 + 30 + len(value) * 3 + 5}" y="14">{value}</text>'
        f'</g></svg>'
    )


def extract_from_cov_json():
    """Read coverage.json generated by `pytest --cov-report=json`."""
    with open(COV_JSON) as f:
        data = json.load(f)

    totals = {}
    for filepath, filedata in data.get("files", {}).items():
        key = "hft-engine" if "hft_engine" in filepath else "agentic-finance" if "agentic_finance" in filepath else None
        if key is None:
            continue
        if key not in totals:
            totals[key] = {"stmts": 0, "miss": 0}
        totals[key]["stmts"] += filedata["summary"]["num_statements"]
        totals[key]["miss"] += filedata["summary"]["missing_lines"]

    if not totals:
        return None

    total_stmts = sum(v["stmts"] for v in totals.values())
    total_miss = sum(v["miss"] for v in totals.values())

    return {
        "agentic-finance": round(100 * (1 - totals["agentic-finance"]["miss"] / totals["agentic-finance"]["stmts"]), 1) if totals.get("agentic-finance") and totals["agentic-finance"]["stmts"] else 0,
        "hft-engine": round(100 * (1 - totals["hft-engine"]["miss"] / totals["hft-engine"]["stmts"]), 1) if totals.get("hft-engine") and totals["hft-engine"]["stmts"] else 0,
        "total": round(100 * (1 - total_miss / total_stmts), 1) if total_stmts else 0,
    }


def run_pytest():
    """Run pytest with coverage JSON report."""
    subprocess.run(
        [sys.executable, "-m", "pytest", "agentic-finance/tests/", "hft-engine/tests/",
         "--cov", "--cov-report=json", "-q", "--tb=short"],
        cwd=ROOT, check=False,
    )


def main():
    # Try existing coverage.json first
    if not os.path.exists(COV_JSON):
        run_pytest()

    pcts = extract_from_cov_json()
    if pcts is None:
        print("Could not extract coverage from coverage.json")
        sys.exit(1)

    badges = {
        "coverage-agentic-finance": ("coverage", f"{pcts['agentic-finance']}%", pcts["agentic-finance"]),
        "coverage-hft-engine": ("coverage", f"{pcts['hft-engine']}%", pcts["hft-engine"]),
        "coverage-total": ("coverage", f"{pcts['total']}%", pcts["total"]),
    }

    for name, (label, value, pct) in badges.items():
        path = os.path.join(HERE, f"{name}.svg")
        with open(path, "w") as f:
            f.write(make_svg(label, value, pct))
        print(f"  {path}: {value}")


if __name__ == "__main__":
    main()
